// @ts-check
import { readFileSync } from 'node:fs';
import { defineConfig } from 'astro/config';
import starlight from '@astrojs/starlight';

/** Generated by scripts/generate.mjs (component and API navigation). */
const generated = JSON.parse(readFileSync(new URL('./src/generated/sidebar.json', import.meta.url), 'utf8'));

/**
 * One website (docs/PLAN-ONE-SITE.md OS-3): the docs build under `base: '/docs'`. Starlight adds the
 * base to sidebar links, while the sidebar, the generator, and the content keep full `/docs/...`
 * paths (Markdown links are not rebased), so sidebar links drop the prefix here.
 * @param {any[]} items
 * @returns {any[]}
 */
const unbase = (items) =>
  items.map((item) => ({
    ...item,
    ...(typeof item.link === 'string' ? { link: item.link.replace(/^\/docs(?=\/)/, '') } : {}),
    ...(Array.isArray(item.items) ? { items: unbase(item.items) } : {}),
  }));

export default defineConfig({
  // Canonical host of the one website (OS-2); the docs are its /docs/ section.
  site: 'https://aui.kasadara.com',
  base: '/docs',
  trailingSlash: 'always',
  // No telemetry from the build either (R4-8).
  devToolbar: { enabled: false },
  security: {
    // Hash-based CSP <meta> for every page; no inline code without a hash (R4-8).
    csp: {
      // Microsoft Clarity hosts only, used after the visitor accepts analytics (R14-7).
      directives: ["default-src 'self'", "img-src 'self' data: https://*.clarity.ms https://c.bing.com", "connect-src 'self' https://*.clarity.ms", "font-src 'self'", "object-src 'none'", "base-uri 'none'", "form-action 'none'", "frame-src 'self'"],
      // Starlight and Expressive Code set CSS custom properties in style attributes
      // (sidebar depth, icon sizes, code token colors). Only attributes are allowed:
      // <style> elements and every script stay hash-only. The pages are static, with
      // no user content. Live examples keep the library's full CSP in their own frames.
      scriptDirective: { resources: ["'self'", 'https://www.clarity.ms', 'https://scripts.clarity.ms'] },
      styleDirective: { resources: ["'self'", { resource: "'unsafe-inline'", kind: 'attribute' }] },
    },
  },
  // Fonts and small assets stay files, so font-src needs no data: source.
  vite: { build: { assetsInlineLimit: 0 } },
  integrations: [
    starlight({
      title: 'AbsoluteUI',
      description: 'Framework-neutral, accessible enterprise UI components with zero runtime dependencies.',
      // Light and dark app icons (artifacts/logos). The title text sits beside them, so the logo is
      // decorative (empty alt) and screen readers do not hear the name twice.
      logo: { light: './src/assets/logo-light.svg', dark: './src/assets/logo-dark.svg', alt: '', replacesTitle: false },
      favicon: '/favicon.svg',
      customCss: [
        '@fontsource-variable/inter',
        '@fontsource-variable/bricolage-grotesque',
        '@fontsource-variable/jetbrains-mono',
        './src/styles/theme.css',
        './src/styles/docs.css',
      ],
      components: { Head: './src/components/Head.astro', Footer: './src/components/Footer.astro', SocialIcons: './src/components/SectionLinks.astro' },
      lastUpdated: false,
      editLink: undefined,
      pagination: true,
      tableOfContents: { minHeadingLevel: 2, maxHeadingLevel: 3 },
      expressiveCode: { themes: ['github-dark-default', 'github-light-default'], styleOverrides: { borderRadius: '0.75rem' } },
      sidebar: unbase([
        {
          label: 'Getting started',
          items: [
            { label: 'Introduction', link: '/docs/' },
            { label: 'Installation', link: '/docs/getting-started/installation/' },
            { label: 'Configuration', link: '/docs/getting-started/configuration/' },
            { label: 'Security and CSP', link: '/docs/getting-started/security/' },
            { label: 'License and attribution', link: '/docs/getting-started/license/' },
            { label: 'Privacy and cookies', link: '/docs/getting-started/privacy/' },
          ],
        },
        {
          label: 'Guides',
          items: [
            { label: 'Forms and validation', link: '/docs/guides/forms/' },
            { label: 'Dates and time zones', link: '/docs/guides/dates-and-time-zones/' },
            { label: 'Theming', link: '/docs/guides/theming/' },
            { label: 'Data grid', link: '/docs/guides/data-grid/' },
            { label: 'Charts', link: '/docs/guides/charts/' },
            { label: 'Server data', link: '/docs/guides/server-data/' },
            { label: 'Overlays and focus', link: '/docs/guides/overlays-and-focus/' },
            { label: 'Internationalization', link: '/docs/guides/internationalization/' },
            { label: 'Helpers and services', link: '/docs/guides/helpers-and-services/' },
            { label: 'Business calendars', link: '/docs/guides/business-calendars/' },
            { label: 'Files and downloads', link: '/docs/guides/files-and-downloads/' },
            { label: 'HTTP client', link: '/docs/guides/http/' },
            { label: 'Icons', link: '/docs/guides/icons/' },
            { label: 'AI assistants (MCP)', link: '/docs/guides/ai-assistants/' },
          ],
        },
        // Angular documentation (docs/PLAN-R10-DOCS.md); absent when generated with --no-angular.
        ...(generated.angular ? [{ label: 'Angular', items: generated.angular }] : []),
        { label: 'Components', items: generated.components },
        { label: 'API reference', items: generated.api },
        {
          label: 'Quality',
          items: [
            { label: 'Performance', link: '/docs/quality/performance/' },
            { label: 'Accessibility and compliance', link: '/docs/quality/accessibility/' },
            { label: 'Browser support', link: '/docs/quality/browser-support/' },
          ],
        },
      ]),
    }),
  ],
});
